# AI Office v2.3 Part B Live Conversational Runtime Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found at E:\AI\AI-Office" }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.3-part-b-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @(
 "config\conversational-office",
 "workspace\templates",
 "scripts\conversational-office",
 "docs"
)) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
 param([string]$RelativePath,[string]$Base64Content)
 $Destination = Join-Path $Repository $RelativePath
 $Parent = Split-Path -Parent $Destination
 if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
 if (Test-Path -LiteralPath $Destination -PathType Leaf) {
   $BackupPath = Join-Path $BackupDirectory $RelativePath
   $BackupParent = Split-Path -Parent $BackupPath
   if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
   Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
 }
 [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\conversational-office\runtime-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "config\conversational-office\conversation-response-schema.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "workspace\templates\conversation-response-template.json" -Base64Content "ewogICJzZXNzaW9uX2lkIjogIiIsCiAgInR1cm5faWQiOiAiIiwKICAidXNlcl9tZXNzYWdlX2lkIjogIiIsCiAgImFzc2lzdGFudF9tZXNzYWdlX2lkIjogIiIsCiAgInByb3ZpZGVyIjogIiIsCiAgIm1vZGVsIjogIiIsCiAgInN0YXR1cyI6ICJjb21wbGV0ZWQiLAogICJyZXNwb25zZSI6ICIiLAogICJjcmVhdGVkX2F0IjogIiIKfQo="
Write-EmbeddedFile -RelativePath "scripts\conversational-office\AIOfficeConversationRuntime.Common.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\conversational-office\Invoke-AIOfficeConversationTurn.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\conversational-office\Send-AIOfficeMessage.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\conversational-office\Start-AIOfficeConversation.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\conversational-office\Test-AIOfficeConversationRuntime.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.3-Part-B-Live-Conversational-Runtime.md" -Base64Content ""
$ScriptPaths = @(
 "E:\AI\AI-Office\scripts\conversational-office\AIOfficeConversationRuntime.Common.ps1",
 "E:\AI\AI-Office\scripts\conversational-office\Invoke-AIOfficeConversationTurn.ps1",
 "E:\AI\AI-Office\scripts\conversational-office\Send-AIOfficeMessage.ps1",
 "E:\AI\AI-Office\scripts\conversational-office\Start-AIOfficeConversation.ps1",
 "E:\AI\AI-Office\scripts\conversational-office\Test-AIOfficeConversationRuntime.ps1"
)
foreach ($ScriptPath in $ScriptPaths) {
 $Tokens=$null; $ParseErrors=$null
 [System.Management.Automation.Language.Parser]::ParseFile($ScriptPath,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
 if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $ScriptPath + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; ")) }
}
Write-Host ""
Write-Host "AI Office v2.3 Part B Live Conversational Runtime installed successfully." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan